import{_ as t,o as e,c as s,l as o,t as i,N as n}from"./chunks/framework.Gjrf2Eoj.js";const k=JSON.parse('{"title":"git-for-each-repo | x-cmd man (git man1) | Run a Git command on a list of repositories","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-for-each-repo - Run a Git command on a list of repositories","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-for-each-repo | x-cmd man (git man1) | Run a Git command on a list of repositories"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-for-each-repo - Run a Git command on a list of repositories"}]]},"headers":[],"params":{"isMan":true,"man":"git-for-each-repo","category":"git man1","desc":"Run a Git command on a list of repositories"},"relativePath":"git/man1/git-for-each-repo.md","filePath":"git/man1/git-for-each-repo.md"}'),r={name:"git/man1/git-for-each-repo.md"},l={class:"visually-hidden"},p=n(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-for-each-repo - Run a Git command on a list of repositories</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> for-each-repo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">config</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">arguments</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Run a Git command on a list of repositories. The arguments after the known options or <strong>--</strong> indicator are used as the arguments for the Git subprocess.</p><p>THIS COMMAND IS EXPERIMENTAL. THE BEHAVIOR MAY CHANGE.</p><p>For example, we could run maintenance on each of a list of repositories stored in a <strong>maintenance.repo</strong> config variable using</p><blockquote><pre><code>git for-each-repo --config=maintenance.repo maintenance run
</code></pre></blockquote><p>This will run <strong>git -C &lt;repo&gt; maintenance run</strong> for each value <strong>&lt;repo&gt;</strong> in the multi-valued config variable <strong>maintenance.repo</strong>.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--config=&lt;config&gt;</p><blockquote><p>Use the given config variable as a multi-valued list storing absolute path names. Iterate on that list of paths to run the given arguments.</p><p>These config values are loaded from system, global, and local Git config, as available. If <strong>git for-each-repo</strong> is run in a directory that is not a Git repository, then only the system and global config is used.</p></blockquote><h2 id="subprocess-behavior" tabindex="-1">SUBPROCESS BEHAVIOR <a class="header-anchor" href="#subprocess-behavior" aria-label="Permalink to &quot;SUBPROCESS BEHAVIOR&quot;">​</a></h2><p>If any <strong>git -C &lt;repo&gt; &lt;arguments&gt;</strong> subprocess returns a non-zero exit code, then the <strong>git for-each-repo</strong> process returns that exit code without running more subprocesses.</p><p>Each <strong>git -C &lt;repo&gt; &lt;arguments&gt;</strong> subprocess inherits the standard file descriptors <strong>stdin</strong>, <strong>stdout</strong>, and <strong>stderr</strong>.</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,18);function h(a,c,g,d,m,u){return e(),s("div",null,[o("h1",l,i(a.$params.man),1),p])}const b=t(r,[["render",h]]);export{k as __pageData,b as default};
